{
  "title": "Conversation Insights",
  "body": "<div class="container">
  <h1>Chat Stats</h1>

  <div id="role-counts" class="count-grid"></div>

  <hr />

  <h3>Top 5 Tool Calls</h3>
  <ol id="tool-calls-list"></ol>

  <hr />

  <p>Longest message: <span id="longest-msg" class="val">-</span></p>
</div>",
  "css": ".container { padding: 20px; background: white; border-radius: 8px; font-family: sans-serif; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }
h1 { margin-top: 0; color: #2c3e50; }
.count-grid { display: flex; gap: 10px; }
.stat-item { background: #f8f9fa; padding: 10px; border-radius: 4px; text-align: center; flex: 1; border-left: 3px solid #3498db; }
.stat-item strong { display: block; color: #555; font-size: 0.9em; }
.stat-item span { font-size: 1.2em; font-weight: bold; color: #333; }
ol { padding-left: 20px; }
li { margin-bottom: 4px; color: #444; }
.val { font-weight: bold; color: #e74c3c; }",
  "scripts": [
    "(function() {
  const messages = ml.current.messages;

  // Calculate counts by role
  const counts = { System: 0, User: 0, Assistant: 0, Tool: 0 };
  messages.forEach(m => {
    if (counts[m.role] !== undefined) counts[m.role]++;
  });

  const roleContainer = root.byId['role-counts'];
  roleContainer.children = [];
  Object.entries(counts).forEach(([role, count]) => {
    roleContainer.children.push({
      tag: 'div',
      attrs: { class: 'stat-item' },
      children: [
        { tag: 'strong', text: role },
        { tag: 'span', text: String(count) }
      ]
    });
  });

  // Get the last 5 tool calls names
  const recentCalls = [];
  const extractCalls = (msgs) => {
    if (msgs.length === 0 || recentCalls.length >= 5) return;
    const [msg, ...rest] = msgs;

    if (msg.role === 'assistant' && msg.tool_calls) {
      msg.tool_calls.forEach(tc => {
        if (recentCalls.length < 5) {
          recentCalls.push(tc.function.name);
        }
      });
    }
    extractCalls(rest);
  };

  // Process messages in reverse order (most recent first)
  extractCalls([...messages].reverse());

  const callsList = root.byId['tool-calls-list'];
  callsList.children = [];
  recentCalls.forEach((name, i) => {
    callsList.children.push({ tag: 'li', text: `${i + 1}. ${name}` });
  });

  // Find longest message length
  const maxLen = messages.reduce((max, msg) => {
    const len = (msg.content || "").length;
    return Math.max(max, len);
  }, 0);

  root.byId['longest-msg'].text = `${maxLen} chars`;
})();"
  ]
}
